entries[446226] = { ["name"] = "Fläschchen der unvergänglichen Alpträume", ["text"] = "Wirken in 45 sek.\nReagenzien:\nAlptraumsaat (10), Träger Mantel der Alpträume , Kristallphiole\nFläschchen der unvergänglichen Alpträume\nWird beim Aufheben gebunden\n50\nBenötigtAlchimie\n(250)\nBenutzen: Erhöht die Distanz- und Nahkampfangriffskraft um 45. Die Vorteile dieses Fläschchens wirken nur in Gebieten, die unter dem Einfluss des Alptraums stehen. (30 Sek. Abklingzeit)\n\"Die Flasche scheint nie leer zu werden, egal, wie viel man davon trinkt.\"" }
entries[446228] = { ["name"] = "Alptraumhafte Kraft", ["text"] = "Sofort\nErhöht die Distanz- und Nahkampfangriffskraft um 45. Die Vorteile dieses Fläschchens wirken nur in Gebieten, die unter dem Einfluss des Alptraums stehen." }
