entries[446231] = { ["name"] = "Aufstieg der Schlange", ["text"] = "Sofort\nErfüllt den Zaubernden mit einem Segen der wilden Götter, was die Distanz- und Nahkampfangriffskraft 12 Sek. lang um 150 erhöht." }
entries[446233] = { ["name"] = "Auslöser des Aufstiegs der Schlange", ["text"] = "Gewährt dem Benutzer beim Verursachen von Distanz- oder Nahkampfschaden eine kleine Chance, mit dem Segen der Schlange erfüllt zu werden. Distanz- und Nahkampfangriffskraft 12 Sek. lang um 150 erhöht.\n(Procchance: 3%, 2Min. Abklingzeit)" }
entries[446236] = { ["name"] = "Leerenaufgeladene Unterarmschienen des Herbeirufers", ["text"] = "Wirken in 45 sek.\nTools: Bogenlichtschraubenschlüssel\nReagenzien:\nAlptraumsaat (10), Träger Mantel der Alpträume , Leerenaufgeladene Unterarmschienen , Goldkraftkern (2), Thoriumapparat (2)\nLeerenaufgeladene Unterarmschienen des Herbeirufers\nWird beim Aufheben gebunden\nHandgelenke Stoff\n37 Rüstung\n+7 Ausdauer\n+8 Intelligenz\nHaltbarkeit 35 / 35\n50\nBenötigtIngenieurskunst\n(250)\nAnlegen: Erhöht durch Zauber und magische Effekte zugefügten Schaden und Heilung um bis zu 21.\nAnlegen: Schützt gegen bestimmte Arten von psychischen Angriffen.\nBenutzen: Kanalisiert die Macht der Leere und verleiht 15 Sek. lang Immunität gegenüber Furcht. (10 Min Abklingzeit)\n\"Die besten Ideen aus Ziris ursprünglichen Entwurf mit ein paar zusätzlichen Modifikationen.\"" }
entries[446237] = { ["name"] = "Leerenaufgeladene Unterarmschienen des Rächers", ["text"] = "Wirken in 45 sek.\nReagenzien:\nAlptraumsaat (10), Träger Mantel der Alpträume , Leerenaufgeladene Unterarmschienen , Dichtes Sprengpulver (3), Sternrubin (2)\nLeerenaufgeladene Unterarmschienen des Rächers\nWird beim Aufheben gebunden\nHandgelenke Leder\n75 Rüstung\n+9 Stärke\n+18 Beweglichkeit\n+5 Ausdauer\nHaltbarkeit 40 / 40\n50\nBenötigtIngenieurskunst\n(250)\nAnlegen: Schützt gegen bestimmte Arten von psychischen Angriffen.\nBenutzen: Kanalisiert die Macht der Leere und verleiht 15 Sek. lang Immunität gegenüber Furcht. (10 Min Abklingzeit)\n\"Die besten Ideen aus Ziris ursprünglichen Entwurf mit ein paar zusätzlichen Modifikationen.\"" }
entries[446238] = { ["name"] = "Leerenaufgeladene Unterarmschienen des Beschützers", ["text"] = "Wirken in 45 sek.\nTools: Bogenlichtschraubenschlüssel\nReagenzien:\nAlptraumsaat (10), Träger Mantel der Alpträume , Leerenaufgeladene Unterarmschienen , Goldkraftkern (2), Thoriumröhre (2)\nLeerenaufgeladene Unterarmschienen des Beschützers\nWird beim Aufheben gebunden\nHandgelenke Platte\n275 Rüstung\n+10 Stärke\n+12 Ausdauer\nHaltbarkeit 55 / 55\n50\nBenötigtIngenieurskunst\n(250)\nAnlegen: Erhöht den Blockwert Eures Schildes um 19.\nAnlegen: Schützt gegen bestimmte Arten von psychischen Angriffen.\nBenutzen: Kanalisiert die Macht der Leere und verleiht 15 Sek. lang Immunität gegenüber Furcht. (10 Min Abklingzeit)\n\"Die besten Ideen aus Ziris ursprünglichen Entwurf mit ein paar zusätzlichen Modifikationen.\"" }
