entries[446240] = { ["name"] = "Siegel der lebendigen Träume", ["text"] = "30 Meter Reichweite\nWirken in 3 sek.\nErhaltet ein verzaubertes Siegel der lebendigen Träume, das Euch ermächtigt, wodurch 30 Min. lang der verursachte Schaden und die hervorgerufene Heilung Eurer Zauber um bis zu 30 und Eure Angriffskraft um 30 erhöht wird. Dieser Effekt kann nur außerhalb des Kampfes angewandt werden." }
entries[446243] = { ["name"] = "Siegel der lebendigen Träume", ["text"] = "Wirken in 3 sek.\nTools: Runenverzierte Echtsilberrute\nReagenzien:\nTraumstaub (5)\nVerzaubertes Siegel: Lebendige Träume\nWird beim Aufheben gebunden\nEinzigartig (5)\n50\nBenötigtVerzauberkunst\n(250)\nBenutzen: Erhaltet ein verzaubertes Siegel der lebendigen Träume, das Euch ermächtigt, wodurch 30 Min. lang der verursachte Schaden und die hervorgerufene Heilung Eurer Zauber um bis zu 30 und Eure Angriffskraft um 30 erhöht wird. Dieser Effekt kann nur außerhalb des Kampfes angewandt werden. (30 Min Abklingzeit)" }
