entries[446336] = { ["name"] = "Atal'aimojo des Krieges", ["text"] = "Sofort\nErhöht die Nahkampf- und Distanzangriffskraft um 48. Bei Nahkampf- und Distanzangriffen besteht eine Chance, größer zu werden, wodurch 10 Sek. lang die Stärke oder Beweglichkeit um 35 erhöht wird (je nach dem, welcher Wert höher ist). Es kann immer nur ein Trank der Atal'ai zur selben Zeit aktiv sein. Dies hat außerhalb des Versunkenen Tempels keinen Effekt.\n(Procchance: 15%, 40s Abklingzeit)" }
entries[446338] = { ["name"] = "Kettenblitzschlag", ["text"] = "150 Mana 30 Meter Reichweite\nWirken in 3 sek. 6 sek. Abklingzeit\nTrifft einen Gegner mit einem Blitzschlag, der auf einen Gegner in der Nähe überspringt. Der Zauber wirkt sich auf bis zu 3 Ziele aus und verursacht bei jedem folgenden Ziel immer größeren Naturschaden." }
